// во что его превращает компилятор (упрощённо):
struct SumAsyncStateMachine : IAsyncStateMachine
{
    public int state;                 // -1 — начало, 0 и 1 — на каком await остановились
    public AsyncTaskMethodBuilder<int> builder;
    public int a, b;                  // локальные переменные стали полями
    public TaskAwaiter<int> awaiter;  // awaiter текущего await
    public void MoveNext() { /* switch (state) … — см. стенд */ }
}

